// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // The reference C's oracle() returns a different address than C itself.
        // The mutant returns address(this), which equals address(c).
        // So the general rule is: c.oracle() != address(c)
        assertTrue(address(c.oracle()) != address(c));
    }
}

